#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail
set +x

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  if ! _read_terminal "  $YELLOW? $1 [y/N] " visible; then return 1; fi
  reply="$REPLY"
  REPLY=""
  [[ "$reply" =~ ^[Yy] ]]
}

_read_terminal() {
  local prompt="$1" visibility="$2" input=""
  REPLY=""
  if [[ ! -t 0 || ! -r /dev/tty ]]; then
    warn "an interactive terminal is required for this step"
    return 1
  fi
  if ! printf '%s' "$prompt" >/dev/tty 2>/dev/null; then
    warn "an interactive terminal is required for this step"
    return 1
  fi
  if [[ "$visibility" == "hidden" ]]; then
    if ! IFS= read -r -s input 2>/dev/null </dev/tty; then
      printf '\n' >/dev/tty 2>/dev/null || true
      warn "could not read from the interactive terminal"
      return 1
    fi
    printf '\n' >/dev/tty 2>/dev/null || true
  elif ! IFS= read -r input 2>/dev/null </dev/tty; then
    warn "could not read from the interactive terminal"
    return 1
  fi
  REPLY="$input"
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_validate_env_file_path() {
  [[ -n "$ENV_FILE" && "$ENV_FILE" == /* && ! -L "$ENV_FILE" ]] || return 1
  local env_parent env_name repo_root script_directory filesystem_type link_count file_mode
  env_parent="${ENV_FILE%/*}"
  env_name="${ENV_FILE##*/}"
  [[ -n "$env_parent" ]] || env_parent="/"
  [[ -n "$env_name" && "$env_name" != "." && "$env_name" != ".." ]] || return 1
  env_parent=$(cd "$env_parent" 2>/dev/null && pwd -P) || return 1
  ENV_FILE="$env_parent/$env_name"
  [[ ! -L "$ENV_FILE" ]] || return 1
  case "$(uname -s)" in
    Linux*)
      filesystem_type=$(stat -f -c '%T' "$env_parent" 2>/dev/null) || return 1
      case "$filesystem_type" in
        ext2|ext3|ext4|ext2/ext3|xfs|btrfs|tmpfs) ;;
        *) return 1 ;;
      esac
      ;;
    Darwin*)
      filesystem_type=$(stat -f '%T' "$env_parent" 2>/dev/null) || return 1
      case "$filesystem_type" in
        apfs|hfs) ;;
        *) return 1 ;;
      esac
      ;;
    *) return 1 ;;
  esac
  script_directory=$(_script_directory) || return 1
  repo_root=$(git -C "$script_directory" rev-parse --show-toplevel 2>/dev/null) || return 1
  repo_root=$(cd "$repo_root" 2>/dev/null && pwd -P) || return 1
  case "$ENV_FILE" in
    "$repo_root"|"$repo_root"/*) return 1 ;;
  esac
  if [[ -e "$ENV_FILE" ]]; then
    [[ -f "$ENV_FILE" && ! -L "$ENV_FILE" ]] || return 1
    link_count=$(stat -c '%h' "$ENV_FILE" 2>/dev/null) ||
      link_count=$(stat -f '%l' "$ENV_FILE" 2>/dev/null) || return 1
    [[ "$link_count" == "1" ]] || return 1
    file_mode=$(stat -c '%a' "$ENV_FILE" 2>/dev/null) ||
      file_mode=$(stat -f '%Lp' "$ENV_FILE" 2>/dev/null) || return 1
    [[ "$file_mode" =~ ^[0-7]+$ ]] || return 1
    (( (8#$file_mode & 077) == 0 )) || return 1
  fi
  return 0
}

_script_directory() {
  local source="${BASH_SOURCE[0]}" source_directory target iteration=0
  source_directory=$(cd -P "$(dirname "$source")" 2>/dev/null && pwd) || return 1
  source="$source_directory/$(basename "$source")"
  while [[ -L "$source" ]]; do
    iteration=$((iteration + 1))
    (( iteration <= 40 )) || return 1
    target=$(readlink "$source") || return 1
    if [[ "$target" == /* ]]; then
      source="$target"
    else
      source="$source_directory/$target"
    fi
    source_directory=$(cd -P "$(dirname "$source")" 2>/dev/null && pwd) || return 1
    source="$source_directory/$(basename "$source")"
  done
  printf '%s\n' "$source_directory"
}

_existing() {
  [[ -n "$ENV_FILE" ]] || return 1
  _validate_env_file_path || return 1
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  if [[ ! -t 0 || ! -r /dev/tty ]]; then
    warn "an interactive terminal is required for this step"
    return 1
  fi
  read -e -r -p "$p" input </dev/tty || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" input rc=0
  _read_terminal "  $BOLD$prompt$RESET " hidden || return 1
  input="$REPLY"
  REPLY=""
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Requires a private, non-symlink file on a
# filesystem that enforces POSIX permissions; every replacement is mode 0600.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''" env_parent grep_status file_mode
  if [[ ! "$key" =~ ^[A-Za-z_][A-Za-z0-9_]*$ ]]; then
    warn "refusing an invalid environment variable name"
    return 1
  fi
  if ! _validate_env_file_path; then
    warn "set ENV_FILE to an absolute, non-symlink path outside the Git repository"
    return 1
  fi
  env_parent="${ENV_FILE%/*}"
  if [[ -L "$ENV_FILE" || ( -e "$ENV_FILE" && ! -f "$ENV_FILE" ) ]]; then
    warn "ENV_FILE must be a regular, non-symlink file path"
    return 1
  fi

  tmp=$(mktemp "$env_parent/.wizard-env.XXXXXX") || {
    warn "could not create a temporary environment file"
    return 1
  }
  if [[ -e "$ENV_FILE" ]]; then
    if [[ ! -r "$ENV_FILE" ]]; then
      rm -f "$tmp"
      warn "ENV_FILE must be a readable regular file when it already exists"
      return 1
    fi
    if grep -vE "^${key}=" "$ENV_FILE" > "$tmp"; then
      :
    else
      grep_status=$?
      if (( grep_status != 1 )); then
        rm -f "$tmp"
        warn "could not read ENV_FILE safely"
        return 1
      fi
    fi
  fi
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  if ! chmod 600 "$tmp"; then
    rm -f "$tmp"
    warn "could not set restrictive permissions on the external environment file"
    return 1
  fi
  file_mode=$(stat -c '%a' "$tmp" 2>/dev/null) ||
    file_mode=$(stat -f '%Lp' "$tmp" 2>/dev/null) || file_mode=""
  if [[ "$file_mode" != "600" || -L "$ENV_FILE" ]] || ! mv -f "$tmp" "$ENV_FILE"; then
    rm -f "$tmp"
    warn "could not safely update the external environment file"
    return 1
  fi
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret REPOSITORY NAME VALUE sets one GitHub Actions secret after confirmation.
set_secret() {
  local repository="$1" name="$2" value="$3"
  if [[ ! "$repository" =~ ^[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9_.-]+$ ]]; then
    warn "refusing a GitHub secret without an explicit owner/repository"
    return 1
  fi
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    SKIPPED+=("GitHub secret $name in $repository (gh unavailable or unauthenticated)")
    warn "skipped GitHub secret $name in $repository: gh is not ready"
    return 0
  fi
  if ! confirm "Set GitHub secret $name in $repository?"; then
    SKIPPED+=("GitHub secret $name in $repository (not authorized)")
    warn "did not set GitHub secret $name in $repository"
    return 0
  fi
  if printf '%s' "$value" | gh secret set "$name" --repo "$repository" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$repository:$name")
    printf '  %s✓ set%s GitHub secret %s in %s\n' "$GREEN" "$RESET" "$name" "$repository"
    return 0
  fi
  SKIPPED+=("GitHub secret $name in $repository (write failed)")
  warn "could not set GitHub secret $name in $repository"
}

# set_var REPOSITORY NAME VALUE sets one GitHub Actions repo variable after confirmation.
set_var() {
  local repository="$1" name="$2" value="$3"
  if [[ ! "$repository" =~ ^[A-Za-z0-9][A-Za-z0-9-]*/[A-Za-z0-9_.-]+$ ]]; then
    warn "refusing a GitHub variable without an explicit owner/repository"
    return 1
  fi
  if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
    SKIPPED+=("GitHub variable $name in $repository (gh unavailable or unauthenticated)")
    warn "skipped GitHub variable $name in $repository: gh is not ready"
    return 0
  fi
  if ! confirm "Set GitHub variable $name in $repository?"; then
    SKIPPED+=("GitHub variable $name in $repository (not authorized)")
    warn "did not set GitHub variable $name in $repository"
    return 0
  fi
  if printf '%s' "$value" | gh variable set "$name" --repo "$repository" >/dev/null 2>&1; then
    printf '  %s✓ set%s GitHub variable %s in %s\n' "$GREEN" "$RESET" "$name" "$repository"
    return 0
  fi
  SKIPPED+=("GitHub variable $name in $repository (write failed)")
  warn "could not set GitHub variable $name in $repository"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=1

banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
step "Enter the exact GitHub repository that needs the CI secret."
ask GITHUB_REPOSITORY "GitHub repository (OWNER/REPO):"
set_secret "$GITHUB_REPOSITORY" STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
